parameters.jsCode:
// n8n Code node (JavaScript)
// Goal: change $binary.data.fileName so WhatsApp shows only the base filename

const items = $input.all().map(item => {
  if (!item.binary || !item.binary.data) return item;

  // 1) pick a source path for the filename
  //    prefer the binary's current fileName, fall back to JSON.name if present
  const raw = item.binary.data.fileName || item.json?.name || '';

  // 2) decode any %2F etc and then take only the last path segment
  const decoded = decodeURIComponent(raw);
  const base = decoded.split('/').pop(); // handles both "a/b/c.pdf" and "a%2Fb%2Fc.pdf" after decode

  // 3) set the clean filename back on the binary
  item.binary.data.fileName = base || 'document.pdf';

  // (optional) ensure mimeType is present
  if (!item.binary.data.mimeType) {
    item.binary.data.mimeType = 'application/pdf';
  }

  return item;
});

return items;

